#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5
# This wizard handles signing passwords: nothing is ever written to a .env file
# and the backup location is never recorded.
ENV_FILE=/dev/null

REPO_ROOT=$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel 2>/dev/null || true)

banner "GameBridge release signing: keystore and GitHub secrets"

# ── 1. Tools and GitHub login ─────────────────────────────────────────────
stage "Tools and GitHub login"
say "Checking what this wizard needs."
missing=()
for tool in keytool gh base64 sha256sum; do
  if command -v "$tool" >/dev/null 2>&1; then say "✓ $tool"; else say "✗ $tool"; missing+=("$tool"); fi
done
if (( ${#missing[@]} )); then
  warn "Missing: ${missing[*]}. Install them and re-run (keytool comes with a JDK)."
  exit 1
fi
if gh auth status >/dev/null 2>&1; then
  say "✓ gh is logged in to GitHub"
else
  warn "gh is not logged in."
  say "In another terminal run:  gh auth login"
  say "Choose GitHub.com, HTTPS, and log in through the browser."
  pause "Press Enter once gh auth status shows you are logged in"
  gh auth status >/dev/null 2>&1 || { warn "Still not logged in. Re-run when it is."; exit 1; }
fi

# ── 2. GitHub repository ──────────────────────────────────────────────────
stage "GitHub repository"
say "The release workflow runs in your GitHub repository, so the secrets go there."
note "This checkout may have no remote; the repository must exist on GitHub."
if confirm "Does the GameBridge repository already exist on GitHub?"; then :; else
  open_url "https://github.com/new"
  step "Create the repository (private or public), without adding files."
  pause "Press Enter when it exists"
fi
ask GITHUB_REPO "Repository as owner/name (for example yourname/gamebridge):"
export GH_REPO="$GITHUB_REPO"
if ! gh repo view "$GH_REPO" >/dev/null 2>&1; then
  warn "Could not see $GH_REPO with your gh login. Check the name and your access, then re-run."
  exit 1
fi
say "✓ found $GH_REPO"
note "GitHub secrets are set on this repository only. Push your code there before you tag."

# ── 3. Keystore ───────────────────────────────────────────────────────────
stage "Release keystore"
say "The keystore is the signing key. Players can only update GameBridge with the same key."
warn "If you lose it, players must uninstall GameBridge before installing the next release."
DEFAULT_KS="$HOME/.gamebridge-signing/release.jks"
ask KEYSTORE_PATH "Keystore path (Enter uses $DEFAULT_KS):" || true
KEYSTORE_PATH="${KEYSTORE_PATH:-$DEFAULT_KS}"
KEYSTORE_PATH="${KEYSTORE_PATH/#\~/$HOME}"
mkdir -p "$(dirname "$KEYSTORE_PATH")"
KS_ABS="$(cd "$(dirname "$KEYSTORE_PATH")" && pwd)/$(basename "$KEYSTORE_PATH")"
if [[ -n "$REPO_ROOT" && "$KS_ABS" == "$REPO_ROOT"/* ]]; then
  warn "That path is inside the repository. A keystore must never be committed."
  warn "Choose a path outside $REPO_ROOT and re-run."
  exit 1
fi
KEYSTORE_PATH="$KS_ABS"

ask KEY_ALIAS_IN "Key alias (Enter uses gamebridge):" || true
KEY_ALIAS_IN="${KEY_ALIAS_IN:-gamebridge}"

ask_secret STORE_PASSWORD "Keystore password (12+ characters, used for the key too):"
if (( ${#STORE_PASSWORD} < 12 )); then warn "Use at least 12 characters."; exit 1; fi
ask_secret STORE_PASSWORD_AGAIN "Type it again:"
if [[ "$STORE_PASSWORD" != "$STORE_PASSWORD_AGAIN" ]]; then warn "The two did not match."; exit 1; fi
note "Keep this password in a password manager. It is not saved anywhere by this wizard."
export GB_STORE_PASSWORD="$STORE_PASSWORD"

if [[ -e "$KEYSTORE_PATH" ]]; then
  say "A keystore already exists at that path. It will not be overwritten."
  if ! keytool -list -keystore "$KEYSTORE_PATH" -storepass:env GB_STORE_PASSWORD -alias "$KEY_ALIAS_IN" >/dev/null 2>&1; then
    warn "That password and alias do not open the existing keystore."
    exit 1
  fi
  say "✓ existing keystore opens with that password and alias"
else
  ask KEY_CN "Your name or organisation for the certificate (for example GameBridge maintainer):"
  KEY_CN="${KEY_CN:-GameBridge maintainer}"
  say "Generating a 4096-bit RSA key valid for about 27 years (Android needs a long validity)."
  keytool -genkeypair -keystore "$KEYSTORE_PATH" -alias "$KEY_ALIAS_IN" \
    -keyalg RSA -keysize 4096 -validity 10000 \
    -dname "CN=$KEY_CN" \
    -storepass:env GB_STORE_PASSWORD -keypass:env GB_STORE_PASSWORD >/dev/null
  chmod 600 "$KEYSTORE_PATH"
  say "✓ keystore created"
fi
KS_SHA=$(sha256sum "$KEYSTORE_PATH" | cut -d' ' -f1)
note "keystore SHA-256: $KS_SHA"

# ── 4. Offline backup ─────────────────────────────────────────────────────
stage "Offline backup"
say "Copy the keystore to somewhere offline that is not this computer's only disk:"
step "a USB stick or an external drive kept somewhere safe, and/or your password manager's file storage."
say "The file to copy is the one at the path you chose above."
note "This wizard does not record where you put the backup. You must remember it."
pause "Press Enter once the copy exists"
ask BACKUP_PATH "Path of the backup copy, to check it matches (blank to skip the check):" || true
if [[ -n "${BACKUP_PATH:-}" ]]; then
  BACKUP_PATH="${BACKUP_PATH/#\~/$HOME}"
  if [[ -f "$BACKUP_PATH" ]] && [[ "$(sha256sum "$BACKUP_PATH" | cut -d' ' -f1)" == "$KS_SHA" ]]; then
    say "✓ the backup matches the keystore (same SHA-256)"
  else
    warn "That file is missing or differs from the keystore. Fix the backup and re-run."
    exit 1
  fi
else
  SKIPPED+=("Backup not checked: confirm your offline copy matches $KS_SHA")
fi
if ! confirm "Does an offline backup of the keystore exist, and do you know where it is?"; then
  warn "Do not tag a release without one. Make the backup, then re-run."
  exit 1
fi

# ── 5. GitHub secrets ─────────────────────────────────────────────────────
stage "GitHub secrets"
say "Setting the four secrets the release workflow reads, on $GH_REPO:"
step "GAMEBRIDGE_KEYSTORE_BASE64, GAMEBRIDGE_KEYSTORE_PASSWORD, GAMEBRIDGE_KEY_ALIAS, GAMEBRIDGE_KEY_PASSWORD"
warn "This overwrites any existing secrets with these names."
confirm "Set them now?" || { warn "Nothing was set."; exit 1; }
KEYSTORE_B64=$(base64 < "$KEYSTORE_PATH" | tr -d '\n')
set_secret GAMEBRIDGE_KEYSTORE_BASE64 "$KEYSTORE_B64"
set_secret GAMEBRIDGE_KEYSTORE_PASSWORD "$STORE_PASSWORD"
set_secret GAMEBRIDGE_KEY_ALIAS "$KEY_ALIAS_IN"
set_secret GAMEBRIDGE_KEY_PASSWORD "$STORE_PASSWORD"
unset GB_STORE_PASSWORD STORE_PASSWORD STORE_PASSWORD_AGAIN KEYSTORE_B64
say "Checking they exist:"
listed=$(gh secret list -R "$GH_REPO" 2>/dev/null | cut -f1 || true)
for name in GAMEBRIDGE_KEYSTORE_BASE64 GAMEBRIDGE_KEYSTORE_PASSWORD GAMEBRIDGE_KEY_ALIAS GAMEBRIDGE_KEY_PASSWORD; do
  if grep -qx "$name" <<<"$listed"; then say "✓ $name"; else warn "✗ $name is not listed"; fi
done
note "Next: bump versionCode in app/build.gradle.kts, push to $GH_REPO, tag vX.Y.Z (matching versionName), and the workflow builds a signed pre-release."

finish
}

run_wizard "$@"; exit
